? "상당함" : (army >= 30 ? "미약" : (army >= 10 ? "이름뿐" : ("없음"))))"},{"id":"sec_out_txt","label":"외부보안","expr":"threat >= 75 ? "매우 취약" : (threat >= 55 ? "취약" : (threat >= 35 ? "불안" : (threat >= 15 ? "보통" : ("안정"))))"},{"id":"sec_in_txt","label":"내부보안","expr":"unrest >= 75 ? "매우 취약" : (unrest >= 55 ? "취약" : (unrest >= 35 ? "불안" : (unrest >= 15 ? "보통" : ("안정"))))"},{"id":"fame_txt","label":"명성","expr":"fame >= 80 ? "드높음" : (fame >= 55 ? "알려짐" : (fame >= 30 ? "들리는 정도" : (fame >= 10 ? "미미함" : ("무명"))))"},{"id":"diff_txt","label":"난이도","expr":"(hardship >= 75 ? "가혹" : (hardship >= 45 ? "보통" : ("온건"))) + " (시련 " + hardship + " · 시세 " + hire_mult + "%)""},{"id":"rel_n_txt","expr":"rel_n >= 85 ? "동맹" : (rel_n >= 65 ? "우호" : (rel_n >= 45 ? "거래 상대" : (rel_n >= 25 ? "관망" : (rel_n >= 10 ? "이름만 앎" : ("미인지")))))"},{"id":"rel_e_txt","expr":"rel_e >= 85 ? "동맹" : (rel_e >= 65 ? "우호" : (rel_e >= 45 ? "거래 상대" : (rel_e >= 25 ? "관망" : (rel_e >= 10 ? "이름만 앎" : ("미인지")))))"},{"id":"rel_s_txt","expr":"rel_s >= 85 ? "동맹" : (rel_s >= 65 ? "우호" : (rel_s >= 45 ? "거래 상대" : (rel_s >= 25 ? "관망" : (rel_s >= 10 ? "이름만 앎" : ("미인지")))))"},{"id":"rel_w_txt","expr":"rel_w >= 85 ? "동맹" : (rel_w >= 65 ? "우호" : (rel_w >= 45 ? "거래 상대" : (rel_w >= 25 ? "관망" : (rel_w >= 10 ? "이름만 앎" : ("미인지")))))"},{"id":"rel_cap_txt","expr":"rel_cap >= 85 ? "동맹" : (rel_cap >= 65 ? "우호" : (rel_cap >= 45 ? "거래 상대" : (rel_cap >= 25 ? "관망" : (rel_cap >= 10 ? "이름만 앎" : ("미인지")))))"},{"id":"neighbors","label":"이웃","expr":""북 모르웬 백작 5일 " + rel_n_txt + " | " + "동 리아나 백작 강 4일·길 7일 " + rel_e_txt + " | " + "남 발레리우스 백작 3일 " + rel_s_txt + " | " + "서 실바나 후작 6일 " + rel_w_txt + " | " + "왕도 알라릭 여왕 14일 " + rel_cap_txt"},{"id":"rel_top","label":"가장 아는 쪽","expr":"max(max(max(rel_n, rel_e), max(rel_s, rel_w)), rel_cap)"},{"id":"food_txt","label":"식량 사정","expr":"food <= 0 ? "바닥 — 오늘 굶는다" : (food_days <= 3 ? "사흘치도 없다" : (surplus >= 0 ? "자급된다" : "축내는 중"))"},{"id":"water_txt","label":"식수 사정","expr":"water <= 0 ? "바닥 — 오늘 마실 물이 없다" : (water_days <= 3 ? "사흘치도 없다" : (water_bal >= 0 ? "자급된다" : "축내는 중"))"},{"id":"phase","label":"국면","expr":"pop >= 400 ? "번성" : (pop >= 220 ? "성장" : (grown > 0 and drawn > 0 ? "자립" : "연명"))"}],"rules":{"onTurn":[{"set":"day","expr":"elapsed"},{"list":"contracts","expire":"day"},{"list":"projects","expire":"day"},{"list":"favors","expire":"day","keepOverdue":true},{"set":"lack_food","expr":"surplus >= 0 ? (food <= 0 and surplus == 0 ? span : 0) : clamp(span - ceil(food / (0 - surplus)) + 1, 0, span)"},{"set":"lack_water","expr":"water_bal >= 0 ? (water <= 0 and water_bal == 0 ? span : 0) : clamp(span - ceil(water / (0 - water_bal)) + 1, 0, span)"},{"set":"lack_gold","expr":"net_gold >= 0 ? (gold <= 0 and net_gold == 0 ? span : 0) : clamp(span - ceil(gold / (0 - net_gold)) + 1, 0, span)"},{"set":"food","expr":"max(0, food + surplus * span)"},{"set":"water","expr":"max(0, water + water_bal * span)"},{"set":"gold","expr":"max(0, gold + net_gold * span)"},{"set":"health","expr":"clamp(health - 7 * max(lack_food, lack_water) + (surplus > 0 ? 2 : 1) * (span - max(lack_food, lack_water)) + (round(d_care * 0.5) - (rations == "절약" ? 1 : 0)) * span, 0, 100)"},{"set":"morale","expr":"clamp(morale - 6 * lack_food + (span - lack_food) + (round(d_home * 0.5) + min(floor(duty_idle / 3), 2) - (rations == "절약" ? 1 : 0) - (unrest >= 55 ? 3 : 0) - (disaster != "" ? 2 : 0)) * span, 0, 100)"},{"set":"unrest","expr":"clamp(unrest + ((guard_men + army + d_guard * 2 < round(pop * 0.10) ? 2 : -3) + (pop > cap ? 3 : 0) - round(d_admin * 0.5)) * span + 5 * lack_food + (army > 0 or count(corps) > 0 ? 3 * lack_gold : 0), 0, 100)"},{"set":"fame","expr":"clamp(fame + ((surplus > 4 ? 2 : 0) - (unrest >= 60 ? 2 : 0)) * span, 0, 100)"},{"set":"pop","expr":"max(0, pop + ((surplus > 4 and fame >= 12 and pop < cap ? round(min(surplus * 0.2, 5)) : 0) - (health <= 10 ? round(pop * 0.03) : 0)) * min(span, 5) - round(pop * 0.04) * min(lack_food, 5))"},{"set":"o_n","expr":"o_n >= 0 ? o_n : (exp_n >= 100 ? max(0, rand(0, 5) - 1) : -1)"},{"set":"o_w","expr":"o_w >= 0 ? o_w : (exp_w >= 100 ? max(0, rand(0, 5) - 1) : -1)"},{"set":"o_s","expr":"o_s >= 0 ? o_s : (exp_s >= 100 ? max(0, rand(0, 5) - 1) : -1)"},{"set":"o_e","expr":"o_e >= 0 ? o_e : (exp_e >= 100 ? max(0, rand(0, 5) - 1) : -1)"},{"set":"exp_n","expr":"exp_n >= 110 ? 0 : (exp_n >= 100 ? 110 + (f_n == 0 ? o_n : (f_n - 1 < o_n ? f_n - 1 : f_n)) : (explore_dir == "북 산맥" ? min(100, exp_n + round(scout_men * (0.6 + f_n * 0.1)) * span) : exp_n))"},{"set":"exp_w","expr":"exp_w >= 110 ? 0 : (exp_w >= 100 ? 110 + (f_w == 0 ? o_w : (f_w - 1 < o_w ? f_w - 1 : f_w)) : (explore_dir == "서 숲" ? min(100, exp_w + round(scout_men * (0.6 + f_w * 0.1)) * span) : exp_w))"},{"set":"exp_s","expr":"exp_s >= 110 ? 0 : (exp_s >= 100 ? 110 + (f_s == 0 ? o_s : (f_s - 1 < o_s ? f_s - 1 : f_s)) : (explore_dir == "남 평원" ? min(100, exp_s + round(scout_men * (0.6 + f_s * 0.1)) * span) : exp_s))"},{"set":"exp_e","expr":"exp_e >= 110 ? 0 : (exp_e >= 100 ? 110 + (f_e == 0 ? o_e : (f_e - 1 < o_e ? f_e - 1 : f_e)) : (explore_dir == "동 강가" ? min(100, exp_e + round(scout_men * (0.6 + f_e * 0.1)) * span) : exp_e))"},{"set":"disaster_days","expr":"max(0, disaster_days - span)"},{"set":"blight","expr":"max(0, blight - span)"},{"set":"disaster","expr":"disaster_days <= 0 ? "" : disaster"},{"set":"route_days","expr":"route == "없음" ? 0 : max(0, route_days - span)"},{"set":"route","expr":"route_days <= 0 ? "없음" : route"},{"set":"appt_in","expr":"appt == "" ? 0 : (appt_in > 0 and appt_in - span < 0 ? 0 : max(-1, appt_in - span))"},{"set":"appt","expr":"appt_in < 0 ? "" : appt"},{"set":"appt_in","expr":"appt == "" ? 0 : appt_in"},{"set":"lead_who","expr":"pw_cass >= pw_orel and pw_cass >= pw_lili ? "카산드라" : (pw_orel >= pw_lili ? "오렐리아" : "릴리아나")"},{"set":"pw_cass","expr":"clamp(pw_cass + ((lead_who == "카산드라" ? -2 : 1) + (stance == "카산드라" ? round(my_weight * 0.05) : (stance == "중립" ? 0 : 0 - round(my_weight * 0.025)))) * min(span, 2), 5, 100)"},{"set":"pw_orel","expr":"clamp(pw_orel + ((lead_who == "오렐리아" ? -2 : 1) + (stance == "오렐리아" ? round(my_weight * 0.05) : (stance == "중립" ? 0 : 0 - round(my_weight * 0.025)))) * min(span, 2), 5, 100)"},{"set":"pw_lili","expr":"clamp(pw_lili + ((lead_who == "릴리아나" ? -2 : 1) + (stance == "릴리아나" ? round(my_weight * 0.05) : (stance == "중립" ? 0 : 0 - round(my_weight * 0.025)))) * min(span, 2), 5, 100)"},{"set":"b_cassandra","expr":"clamp(b_cassandra + (stance == "카산드라" ? (b_cassandra >= 40 ? 0 : 1) : (stance == "중립" or exposed < 40 ? 0 : (b_cassandra <= -20 ? 0 : -1))) * min(span, 2), -50, 100)"},{"set":"b_orelia","expr":"clamp(b_orelia + (stance == "오렐리아" ? (b_orelia >= 40 ? 0 : 1) : (stance == "중립" or exposed < 40 ? 0 : (b_orelia <= -20 ? 0 : -1))) * min(span, 2), -50, 100)"},{"set":"b_liliana","expr":"clamp(b_liliana + (stance == "릴리아나" ? (b_liliana >= 40 ? 0 : 1) : (stance == "중립" or exposed < 40 ? 0 : (b_liliana <= -20 ? 0 : -1))) * min(span, 2), -50, 100)"},{"set":"exposed","expr":"clamp(exposed + (stance == "중립" ? (day >= 60 ? 1 : -2) : 4) * min(span, 2), 0, 100)"},{"set":"day_prev","expr":"day"},{"set":"lack_food","expr":"0"},{"set":"lack_water","expr":"0"},{"set":"lack_gold","expr":"0"}],"events":[{"id":"find_n_1","once":true,"when":"exp_n == 110","effects":[{"set":"f_n","expr":"f_n + 1"}],"notify":"[탐사 · 북 산맥] 칼날 능선에서 캐거나 베거나 걷어 낼 것이 나왔다. 무엇이고 어디에 쓰는 것인지를 이번 장면에서 정하고 이름을 붙여라 — 이름이 붙지 않으면 기록에 남지 않는다. 예컨대 드러난 화강암 노두(성벽 쌓을 돌), 바위산의 산양 떼(모피와 젖) — 어디까지나 예시다. 이 땅에 더 어울리는 것이 떠오르면 그쪽을 써라. 이미 나온 것과 겹치지만 마라."},{"id":"find_n_2","once":true,"when":"exp_n == 111","effects":[{"set":"f_n","expr":"f_n + 1"}],"notify":"[탐사 · 북 산맥] 칼날 능선에서 거기 사는 것과 마주쳤다. 정체는 이미 정해져 있다 — 고블린 부족들이다 — 능선 곳곳에 퍼져 살고, 수가 많다. 밤에 내려오는 길목이 이제 지도에 잡혔다. 이 사실 그대로 이번 장면에 그리고 기록에 올려라. 다른 것으로 바꾸지 마라."},{"id":"find_n_3","once":true,"when":"exp_n == 112","effects":[{"set":"f_n","expr":"f_n + 1"}],"notify":"[탐사 · 북 산맥] 칼날 능선에서 사람 손이 닿았던 자리가 나왔다. 정체는 이미 정해져 있다 — 무너진 옛 수로의 취수구다 — 능선 뒤 암반 안에 맑은 수맥이 갇혀 있고, 옛 사람들은 여기서 물을 끌었다. 손이 모자라 버려졌을 뿐이다. 바위를 깨고 수로를 다시 잇